package com.crm.hr;
import com.crm.hr.dto.CareerEventRequest;import com.crm.hr.dto.LeaveQuotaRequest;import com.crm.hr.entity.CareerEvent;import com.crm.hr.entity.EmployeeDocument;import com.crm.hr.repository.CareerEventRepository;import com.crm.hr.repository.EmployeeDocumentRepository;import com.crm.hr.repository.LeaveQuotaRepository;import com.crm.hr.service.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import org.springframework.mock.web.MockMultipartFile;import java.math.BigDecimal;import java.nio.file.Path;import java.time.LocalDate;import java.util.List;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class EmployeeDossierServiceTest{
 @TempDir Path temp;
 @Test void storesOnlyValidatedPrivatePdfAndReturnsMetadata(){var repository=mock(EmployeeDocumentRepository.class);var validator=mock(EmployeeReferenceValidator.class);var service=new EmployeeDocumentService(repository,validator,temp.toString());var file=new MockMultipartFile("file","cv.pdf","application/pdf","%PDF-test".getBytes());var saved=new EmployeeDocument();saved.setId(2L);when(repository.save(any())).thenAnswer(i->{var d=(EmployeeDocument)i.getArgument(0);d.setId(2L);return d;});var result=service.upload("17","CV",file,"Bearer test");assertEquals("cv.pdf",result.getName());assertTrue(java.nio.file.Files.exists(temp.resolve(result.getStorageKey())));verify(validator).requireExists("17","Bearer test");}
 @Test void rejectsFakePdfBeforePersisting(){var repository=mock(EmployeeDocumentRepository.class);var service=new EmployeeDocumentService(repository,mock(EmployeeReferenceValidator.class),temp.toString());assertThrows(IllegalArgumentException.class,()->service.upload("17","CV",new MockMultipartFile("file","x.pdf","application/pdf","not pdf".getBytes()),"Bearer test"));verify(repository,never()).save(any());}
 @Test void careerEventsUseTheEmployeeAndOrderFromTheRepository(){var repository=mock(CareerEventRepository.class);var validator=mock(EmployeeReferenceValidator.class);var service=new CareerEventService(repository,validator);var request=new CareerEventRequest("17",LocalDate.parse("2026-01-01"),CareerEvent.Type.PROMOTION,"Analyst","Manager","Promotion");when(repository.save(any())).thenAnswer(i->i.getArgument(0));var result=service.create(request,"Bearer test");assertEquals("17",result.getEmployeeId());verify(validator).requireExists("17","Bearer test");}
 @Test void quotaAllocationIsExplicitAndDoesNotCalculateBalance(){var repository=mock(LeaveQuotaRepository.class);var validator=mock(EmployeeReferenceValidator.class);var service=new LeaveQuotaService(repository,validator);var request=new LeaveQuotaRequest("17",LocalDate.parse("2026-01-01"),LocalDate.parse("2026-12-31"),"ANNUAL",new BigDecimal("12.50"));when(repository.save(any())).thenAnswer(i->i.getArgument(0));var result=service.assign(request,"Bearer test");assertEquals(new BigDecimal("12.50"),result.getGrantedDays());verify(validator).requireExists("17","Bearer test");verify(repository).save(any());}
}
